CREATE TABLE `equipo_monitores` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `equipo_id` bigint unsigned NOT NULL,
  `origen_pantalla` enum('INTEGRADA','EXTERNA') COLLATE utf8mb4_unicode_ci NOT NULL,
  `incluido` tinyint(1) NOT NULL DEFAULT '1',
  `pulgadas` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
